ALTER TABLE public.assets ADD COLUMN merged_into_asset_id uuid REFERENCES public.assets(id), ADD COLUMN merged_at timestamptz, ADD COLUMN creation_source text;
CREATE TABLE public.asset_merge_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,keep_id uuid NOT NULL REFERENCES public.assets(id),source_ids uuid[] NOT NULL,snapshot jsonb NOT NULL,merged_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.asset_merge_log TO authenticated; GRANT ALL ON public.asset_merge_log TO service_role;
ALTER TABLE public.asset_merge_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY asset_merge_admin_read ON public.asset_merge_log FOR SELECT TO authenticated USING(org_id=public.get_user_org_id() AND public.has_role_in_org(auth.uid(),org_id,'admin'));
CREATE POLICY assets_hide_merged ON public.assets AS RESTRICTIVE FOR SELECT TO authenticated USING(merged_into_asset_id IS NULL);
CREATE FUNCTION public.canonical_asset_id(_id uuid,_org uuid) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE x uuid:=_id; n uuid; i int; BEGIN FOR i IN 1..20 LOOP SELECT merged_into_asset_id INTO n FROM assets WHERE id=x AND org_id=_org; IF NOT FOUND THEN RETURN NULL; END IF; IF n IS NULL THEN RETURN x; END IF; x:=n; END LOOP; RAISE EXCEPTION 'Invalid asset redirect'; END $$;
REVOKE ALL ON FUNCTION public.canonical_asset_id(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.canonical_asset_id(uuid,uuid) TO authenticated,service_role;
CREATE FUNCTION public.asset_duplicate_review() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); result jsonb; BEGIN IF o IS NULL OR NOT has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Company admin only'; END IF;
WITH groups AS (SELECT site_id,lower(btrim(name)) n,lower(btrim(category)) c FROM assets WHERE org_id=o AND merged_into_asset_id IS NULL AND site_id IS NOT NULL GROUP BY site_id,lower(btrim(name)),lower(btrim(category)) HAVING count(*)>1), rows AS (SELECT a.*,s.name site_name,b.source_filename,(SELECT count(*) FROM jobs j WHERE j.org_id=o AND j.asset_id=a.id) jobs_count,(SELECT count(*) FROM job_sheet_responses r WHERE r.org_id=o AND (r.responses->>'riser_asset_id'=a.id::text OR r.responses#>>'{_riser_visit,asset_id}'=a.id::text)) reports_count,(SELECT count(*) FROM asset_service_history h WHERE h.org_id=o AND h.asset_id=a.id) history_count,(SELECT count(*) FROM asset_documents d WHERE d.org_id=o AND d.asset_id=a.id) documents_count,(SELECT count(*) FROM riser_outlet_tags t WHERE t.org_id=o AND canonical_asset_id(t.asset_id,o)=a.id) outlet_tags_count,(SELECT count(*) FROM riser_outlet_tags t WHERE t.org_id=o AND canonical_asset_id(t.asset_id,o)=a.id AND t.label_printed_at IS NOT NULL) outlet_printed_count FROM assets a JOIN groups g ON a.site_id=g.site_id AND lower(btrim(a.name))=g.n AND lower(btrim(a.category))=g.c JOIN sites s ON s.id=a.site_id AND s.org_id=o LEFT JOIN import_batches b ON b.id=a.import_batch_id AND b.org_id=o WHERE a.org_id=o AND a.merged_into_asset_id IS NULL) SELECT coalesce(jsonb_agg(to_jsonb(rows) ORDER BY site_name,name,created_at,id),'[]') INTO result FROM rows; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.asset_duplicate_review() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.asset_duplicate_review() TO authenticated;
CREATE FUNCTION public.asset_identity_refs(v jsonb,source_ids uuid[],keep_id uuid) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE result jsonb; k text; val jsonb; BEGIN IF jsonb_typeof(v)='object' THEN result:='{}'; FOR k,val IN SELECT * FROM jsonb_each(v) LOOP IF k IN ('riser_asset_id','asset_id','riser_id') AND val #>> '{}' = ANY(ARRAY(SELECT x::text FROM unnest(source_ids) x)) THEN val:=to_jsonb(keep_id::text); ELSE val:=asset_identity_refs(val,source_ids,keep_id); END IF; result:=result||jsonb_build_object(k,val); END LOOP; RETURN result; ELSIF jsonb_typeof(v)='array' THEN SELECT coalesce(jsonb_agg(asset_identity_refs(value,source_ids,keep_id)),'[]') INTO result FROM jsonb_array_elements(v); RETURN result; END IF; RETURN v; END $$;
CREATE FUNCTION public.merge_asset_duplicates(_keep_id uuid,_source_ids uuid[],_preview_token text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); k public.assets; a public.assets; ids uuid[]; snap jsonb; tbl text; records jsonb; token text; result jsonb; latest public.assets; BEGIN
IF o IS NULL OR NOT has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Company admin only'; END IF;
SELECT array_agg(DISTINCT x ORDER BY x) INTO ids FROM unnest(_source_ids) x WHERE x<>_keep_id; IF coalesce(cardinality(ids),0)=0 THEN RAISE EXCEPTION 'Choose at least one duplicate'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(o::text||':asset-merge',0)); PERFORM id FROM assets WHERE id=ANY(ids||ARRAY[_keep_id]) ORDER BY id FOR UPDATE;
SELECT * INTO k FROM assets WHERE id=_keep_id AND org_id=o AND merged_into_asset_id IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Kept asset not found'; END IF;
IF (SELECT count(*) FROM assets WHERE id=ANY(ids) AND org_id=o AND site_id=k.site_id AND lower(btrim(name))=lower(btrim(k.name)) AND lower(btrim(category))=lower(btrim(k.category)) AND merged_into_asset_id IS NULL)<>cardinality(ids) THEN RAISE EXCEPTION 'Only duplicates at the same company/site/name/category can merge'; END IF;
SELECT jsonb_build_object('assets',jsonb_agg(to_jsonb(x) ORDER BY x.id)) INTO snap FROM assets x WHERE id=ANY(ids||ARRAY[_keep_id]) AND org_id=o;
FOR tbl IN SELECT unnest(ARRAY['jobs','asset_documents','ppm_schedules','compliance_records','audits','sensor_readings','digital_twin_health','asset_sensors','defects','asset_service_history','asset_review_flags','historic_reports','riser_outlet_tags','riser_outlet_scans']) LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),''[]''::jsonb) FROM public.%I t WHERE org_id=$1 AND asset_id=ANY($2)',tbl) INTO records USING o,ids||ARRAY[_keep_id]; snap:=snap||jsonb_build_object(tbl,records); END LOOP;
SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]') INTO records FROM job_sheet_responses r WHERE org_id=o AND asset_identity_refs(responses,ids,_keep_id) IS DISTINCT FROM responses; snap:=snap||jsonb_build_object('reports',records); token:=md5(snap::text);
result:=jsonb_build_object('token',token,'keep_tag',k.asset_tag,'remove_count',cardinality(ids),'snapshot',snap,'printed_warning',EXISTS(SELECT 1 FROM assets WHERE id=ANY(ids) AND (label_printed_at IS NOT NULL OR label_status IN ('printed','placed'))) OR EXISTS(SELECT 1 FROM riser_outlet_tags WHERE asset_id=ANY(ids) AND label_printed_at IS NOT NULL)); IF _preview_token IS NULL THEN RETURN result; END IF; IF _preview_token<>token THEN RAISE EXCEPTION 'Records changed since preview. Review again.'; END IF;
INSERT INTO asset_merge_log(org_id,keep_id,source_ids,snapshot,merged_by) VALUES(o,_keep_id,ids,snap,auth.uid());
DELETE FROM asset_service_history h WHERE h.org_id=o AND h.asset_id=ANY(ids) AND h.job_sheet_response_id IS NOT NULL AND EXISTS(SELECT 1 FROM asset_service_history x WHERE x.org_id=o AND x.job_sheet_response_id=h.job_sheet_response_id AND x.asset_id=ANY(ids||ARRAY[_keep_id]) AND (x.asset_id=_keep_id OR (x.asset_id<>_keep_id AND x.id<h.id)));
DELETE FROM digital_twin_health h WHERE h.org_id=o AND h.asset_id=ANY(ids) AND EXISTS(SELECT 1 FROM digital_twin_health x WHERE x.org_id=o AND x.asset_id=ANY(ids||ARRAY[_keep_id]) AND (x.asset_id=_keep_id OR (x.asset_id<>_keep_id AND x.id<h.id)));
FOR a IN SELECT * FROM assets WHERE id=ANY(ids) AND org_id=o ORDER BY id LOOP UPDATE riser_outlet_tags t SET asset_id=_keep_id WHERE t.org_id=o AND t.asset_id=a.id AND NOT EXISTS(SELECT 1 FROM riser_outlet_tags x WHERE x.org_id=o AND x.asset_id=_keep_id AND x.outlet_number=t.outlet_number); END LOOP;
FOR tbl IN SELECT unnest(ARRAY['jobs','asset_documents','ppm_schedules','compliance_records','audits','sensor_readings','digital_twin_health','asset_sensors','defects','asset_service_history','asset_review_flags','historic_reports','riser_outlet_scans']) LOOP EXECUTE format('UPDATE public.%I SET asset_id=$1 WHERE org_id=$2 AND asset_id=ANY($3)',tbl) USING _keep_id,o,ids; END LOOP;
UPDATE job_sheet_responses SET responses=asset_identity_refs(responses,ids,_keep_id) WHERE org_id=o AND asset_identity_refs(responses,ids,_keep_id) IS DISTINCT FROM responses;
SELECT * INTO latest FROM assets WHERE id=ANY(ids||ARRAY[_keep_id]) ORDER BY last_inspection_at DESC NULLS LAST,created_at,id LIMIT 1;
SELECT string_agg('['||coalesce(asset_tag,id::text)||'] '||notes,E'\n' ORDER BY created_at,id) INTO tbl FROM assets WHERE org_id=o AND id=ANY(ids) AND nullif(btrim(notes),'') IS NOT NULL;
UPDATE assets SET notes=concat_ws(E'\n',nullif(notes,''),tbl),last_inspection_at=latest.last_inspection_at,last_inspection_type=latest.last_inspection_type,last_inspection_result=latest.last_inspection_result,last_job_id=latest.last_job_id,last_job_sheet_response_id=latest.last_job_sheet_response_id,attributes=coalesce(attributes,'{}')||jsonb_build_object('duplicate_merge_sources',coalesce(attributes->'duplicate_merge_sources','[]')||(snap->'assets')),outlets_count=coalesce(outlets_count,(SELECT max(outlets_count) FROM assets WHERE id=ANY(ids))),cabinet_key_type=coalesce(cabinet_key_type,(SELECT cabinet_key_type FROM assets WHERE id=ANY(ids) AND cabinet_key_type IS NOT NULL ORDER BY created_at LIMIT 1)) WHERE id=_keep_id AND org_id=o;
UPDATE assets SET merged_into_asset_id=_keep_id,merged_at=now() WHERE org_id=o AND id=ANY(ids); RETURN result-'snapshot'; END $$;
REVOKE ALL ON FUNCTION public.merge_asset_duplicates(uuid,uuid[],text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.merge_asset_duplicates(uuid,uuid[],text) TO authenticated;
CREATE OR REPLACE FUNCTION public.merge_assets(_keep_id uuid,_remove_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Use Assets > Possible duplicates to preview and confirm a safe merge.'; END $$;
CREATE FUNCTION public.upsert_asset_rows(_rows jsonb,_source text DEFAULT 'import') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); v jsonb; a public.assets; existing public.assets; out jsonb:='[]'; inserted boolean; BEGIN IF o IS NULL OR NOT has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Company admin only'; END IF; IF jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows)>5000 THEN RAISE EXCEPTION 'Invalid asset rows'; END IF;
FOR v IN SELECT value FROM jsonb_array_elements(_rows) LOOP a:=jsonb_populate_record(NULL::public.assets,v); IF nullif(btrim(a.name),'') IS NULL THEN RAISE EXCEPTION 'Asset name required'; END IF; IF a.org_id IS NOT NULL AND a.org_id<>o THEN RAISE EXCEPTION 'Another company'; END IF; a.org_id:=o; a.name:=btrim(a.name); a.category:=coalesce(nullif(a.category,''),'general');
IF a.site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sites WHERE id=a.site_id AND org_id=o) THEN RAISE EXCEPTION 'Site not in company'; END IF; IF a.import_batch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM import_batches WHERE id=a.import_batch_id AND org_id=o) THEN RAISE EXCEPTION 'Import not in company'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(o::text||coalesce(a.site_id::text,'none')||lower(a.name)||lower(a.category),0));
SELECT * INTO existing FROM assets WHERE org_id=o AND site_id IS NOT DISTINCT FROM a.site_id AND lower(btrim(name))=lower(a.name) AND lower(btrim(category))=lower(btrim(a.category)) AND merged_into_asset_id IS NULL ORDER BY created_at,id LIMIT 1 FOR UPDATE; inserted:=NOT FOUND;
IF inserted THEN INSERT INTO assets(name,org_id,site_id,category,asset_type,riser_location,outlets_count,asset_tag,status,make,model,serial_number,notes,install_date,warranty_expiry,last_inspection_at,last_inspection_type,last_inspection_result,import_batch_id,imported_at,created_by,creation_source,attributes) VALUES(a.name,o,a.site_id,a.category,a.asset_type,a.riser_location,a.outlets_count,nullif(a.asset_tag,''),coalesce(a.status,'operational'),a.make,a.model,a.serial_number,a.notes,a.install_date,a.warranty_expiry,a.last_inspection_at,a.last_inspection_type,a.last_inspection_result,a.import_batch_id,a.imported_at,auth.uid(),_source,coalesce(a.attributes,'{}')) RETURNING * INTO existing;
ELSE UPDATE assets SET make=coalesce(nullif(a.make,''),make),model=coalesce(nullif(a.model,''),model),serial_number=coalesce(nullif(a.serial_number,''),serial_number),riser_location=coalesce(riser_location,a.riser_location),asset_type=coalesce(asset_type,a.asset_type),outlets_count=coalesce(outlets_count,a.outlets_count),notes=CASE WHEN nullif(a.notes,'') IS NULL OR notes=a.notes THEN notes ELSE concat_ws(E'\n',nullif(notes,''),a.notes) END,attributes=coalesce(attributes,'{}')||jsonb_build_object('last_import',jsonb_build_object('source',_source,'batch_id',a.import_batch_id,'values',v)),last_inspection_at=CASE WHEN a.last_inspection_at>coalesce(last_inspection_at,'-infinity') THEN a.last_inspection_at ELSE last_inspection_at END,last_inspection_type=CASE WHEN a.last_inspection_at>coalesce(last_inspection_at,'-infinity') THEN a.last_inspection_type ELSE last_inspection_type END,last_inspection_result=CASE WHEN a.last_inspection_at>coalesce(last_inspection_at,'-infinity') THEN a.last_inspection_result ELSE last_inspection_result END WHERE id=existing.id AND org_id=o; END IF;
out:=out||jsonb_build_array(jsonb_build_object('id',existing.id,'created',inserted)); END LOOP; RETURN out; END $$;
REVOKE ALL ON FUNCTION public.upsert_asset_rows(jsonb,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.upsert_asset_rows(jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.add_site_risers(_site_id uuid,_locations text[]) RETURNS SETOF uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE loc text; r jsonb; BEGIN FOREACH loc IN ARRAY _locations LOOP IF nullif(btrim(loc),'') IS NULL THEN CONTINUE; END IF; r:=upsert_asset_rows(jsonb_build_array(jsonb_build_object('name','Dry Riser - '||btrim(loc),'site_id',_site_id,'category','Dry Riser','asset_type','Dry Riser','riser_location',btrim(loc))),'riser builder'); RETURN NEXT (r->0->>'id')::uuid; END LOOP; END $$;
CREATE FUNCTION public.asset_outlet_codes(_asset_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); target uuid; result jsonb; BEGIN IF o IS NULL OR is_customer_user(auth.uid()) OR NOT(has_role_in_org(auth.uid(),o,'admin') OR has_role_in_org(auth.uid(),o,'engineer')) THEN RAISE EXCEPTION 'Staff only'; END IF; target:=canonical_asset_id(_asset_id,o); SELECT jsonb_build_object('total',outlets_count,'tags',(SELECT coalesce(jsonb_object_agg(outlet_tag,outlet_number),'{}') FROM riser_outlet_tags t WHERE t.org_id=o AND canonical_asset_id(t.asset_id,o)=target)) INTO result FROM assets WHERE id=target AND org_id=o; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.asset_outlet_codes(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.asset_outlet_codes(uuid) TO authenticated;
DO $patch$ DECLARE d text; BEGIN
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE oid='public.lookup_asset_by_tag(text)'::regprocedure; d:=replace(d,'FROM public.assets a','FROM public.assets source JOIN public.assets a ON a.id=public.canonical_asset_id(source.id,source.org_id) AND a.org_id=source.org_id'); d:=replace(d,'upper(a.asset_tag) = upper(_tag)','upper(source.asset_tag) = upper(_tag)'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE oid='public.sync_asset_from_job_sheet(uuid)'::regprocedure; d:=replace(d,'answers := coalesce(r.responses, ''{}''::jsonb);','answers := coalesce(r.responses, ''{}''::jsonb); PERFORM pg_advisory_xact_lock(hashtextextended(j.org_id::text||j.site_id::text||''riser-sync'',0));'); d:=replace(d,'picked_id := nullif(btrim(answers ->> ''riser_asset_id''), '''')::uuid;','picked_id := public.canonical_asset_id(nullif(btrim(answers ->> ''riser_asset_id''), '''')::uuid,j.org_id);'); d:=replace(d,'AND lower(btrim(coalesce(riser_location, ''''))) = lower(riser_loc)','AND merged_into_asset_id IS NULL AND (lower(btrim(coalesce(riser_location, ''''))) = lower(riser_loc) OR lower(btrim(name)) IN (lower(riser_type||'' - ''||riser_loc),lower(riser_type||'' — ''||riser_loc)))'); d:=replace(d,'concat(riser_type, '' — '', riser_loc)','concat(riser_type, '' - '', riser_loc)'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE oid='public.record_outlet_scan(text)'::regprocedure; d:=replace(d,'a.id = t.asset_id AND a.org_id = t.org_id','a.id = public.canonical_asset_id(t.asset_id,t.org_id) AND a.org_id = t.org_id'); d:=replace(d,'SELECT t.id, t.asset_id, t.outlet_number, a.asset_tag INTO r','SELECT t.id, a.id AS asset_id, t.outlet_number, a.asset_tag INTO r'); EXECUTE d;
END $patch$;